def chain(points):return [line(a,b) for a,b in zip(points[:-1],points[1:])]
def stem(x):return chain([(x-10,490.5),(x,482.5),(x,557.3)])
def arch(x):return [[[x,495],[x+11,486],[x+22,479],[x+32,489]],[[x+32,489],[x+42,498],[x+40.5,511],[x+40.5,521]],line((x+40.5,521),(x+40.5,557.3))]
