def sample(path,n=40):
 t=np.linspace(0,1,n)[:,None];out=[]
 for seg in path:
  a,b,c,d=np.array(seg);out.append((1-t)**3*a+3*(1-t)**2*t*b+3*(1-t)*t*t*c+t**3*d)
 return np.concatenate(out)

def render(paths,angle=30,box=(235,450,775,565),scale=3):
 x,y,xx,yy=box;img=np.zeros(((yy-y)*scale,(xx-x)*scale),np.uint8)
